# Let me analyze where each component moves
from collections import Counter

demo1_in = demo1_input
demo1_out = demo1_output

def get_components_by_color(grid):
    """Get connected components for each color"""
    colors = set(c for row in grid for c in row if c != 0)
    components = {}
    for color in colors:
        components[color] = []
        visited = set()
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == color and (r, c) not in visited:
                    # BFS to find component
                    stack = [(r, c)]
                    comp = []
                    while stack:
                        cr, cc = stack.pop()
                        if (cr, cc) in visited:
                            continue
                        visited.add((cr, cc))
                        comp.append((cr, cc))
                        for dr, dc in [(0,1), (1,0), (0,-1), (-1,0)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == color and (nr, nc) not in visited:
                                stack.append((nr, nc))
                    components[color].append(comp)
    return components

def get_centroid(cells):
    """Get centroid of a set of cells"""
    if not cells:
        return None
    rows = [r for r, c in cells]
    cols = [c for r, c in cells]
    return (sum(rows)/len(rows), sum(cols)/len(cols))

print("=== Demo 1 component analysis ===\n")

in_comps = get_components_by_color(demo1_in)
out_comps = get_components_by_color(demo1_out)

for color in sorted(set(list(in_comps.keys()) + list(out_comps.keys()))):
    print(f"Color {color}:")
    for i, comp in enumerate(in_comps.get(color, [])):
        centroid_in = get_centroid(comp)
        print(f"  Input component {i}: {centroid_in}")

    for i, comp in enumerate(out_comps.get(color, [])):
        centroid_out = get_centroid(comp)
        print(f"  Output component {i}: {centroid_out}")
        if in_comps.get(color, []):
            first_centroid_in = get_centroid(in_comps[color][0])
            dr = centroid_out[0] - first_centroid_in[0]
            print(f"    Shift from first input component: ({dr:.1f}, ...)")

# The key insight might be: components with the same shape transform together
# Let me check if certain shapes coalesce

